WITH customer_stats AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_closed, ROUND((100 * SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit FROM accounts GROUP BY customer_id) SELECT c.id, c.credit_limit, cs.pct_closed, cs.pct_credit FROM customers c INNER JOIN customer_stats cs ON c.id = cs.customer_id ORDER BY pct_closed, id DESC;
